<?php require '../config.php';$d=body();$code=preg_replace('/\D/','',$d['code']??'');$s=db()->prepare("SELECT * FROM games WHERE code=? AND status='lobby'");$s->bind_param('s',$code);$s->execute();$g=$s->get_result()->fetch_assoc();if(!$g)json_response(['error'=>'Jolten tar inte emot fler deltagare.'],404);$name=trim(mb_substr($d['name']??'',0,40));$avatar=mb_substr($d['avatar']??'⚡',0,12);if(!$name)json_response(['error'=>'Ange ett namn.'],422);$token=bin2hex(random_bytes(24));try{$s=db()->prepare('INSERT INTO players(game_id,token,name,avatar) VALUES(?,?,?,?)');$s->bind_param('isss',$g['id'],$token,$name,$avatar);$s->execute();json_response(['token'=>$token]);}catch(mysqli_sql_exception $e){json_response(['error'=>'Namnet används redan i den här Jolten.'],409);}

